set -eu
base=/root/sugarscape/dynasoar-cuda91-002
mkdir -p "$base/diagnostic"
cd "$base/diagnostic"
trap 'run_exit=$?; trap - EXIT; printf "{\"exit_code\": %s}\n" "$run_exit" > terminal.json; tar -C "$base" -czf "$base/complete-evidence.tar.gz" diagnostic; sha256sum "$base/complete-evidence.tar.gz"; exit "$run_exit"' EXIT
printf '%s\n' 'deb http://archive.ubuntu.com/ubuntu focal universe' 'deb http://archive.ubuntu.com/ubuntu focal-updates universe' 'deb http://security.ubuntu.com/ubuntu focal-security universe' > /etc/apt/sources.list.d/sugarscape-toolchain-universe.list
timeout 300 apt-get update > setup.log 2>&1
timeout 300 apt-get install -y skopeo umoci >> setup.log 2>&1
timeout 300 skopeo copy docker://docker.io/library/ubuntu@sha256:a3785f78ab8547ae2710c89e627783cfa7ee7824d3468cae6835c9f4eae23ff7 "oci:$base/ubuntu:16.04" > image-copy.log 2>&1
timeout 120 umoci unpack --rootless --image "$base/ubuntu:16.04" "$base/image" > image-unpack.log 2>&1
cp --remove-destination /etc/resolv.conf "$base/image/rootfs/etc/resolv.conf"
printf '%s'  | base64 -d > selected-packages.json
printf '%s'  | base64 -d > extract_toolkit.py
timeout 600 python3 extract_toolkit.py > toolkit-extract.log 2>&1
timeout 60 chroot "$base/image/rootfs" /usr/local/cuda-9.1/bin/nvcc --version > nvcc-version.txt 2>&1
timeout 300 chroot "$base/image/rootfs" apt-get update > historical-apt.log 2>&1
timeout 300 chroot "$base/image/rootfs" apt-get install -y build-essential >> historical-apt.log 2>&1
chroot "$base/image/rootfs" g++ --version > gcc-version.txt
chroot "$base/image/rootfs" dpkg-query -W > historical-packages.txt
